import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { certificatesAPI } from '../../services/api';
import { Icon, IconSizes, IconColors } from '../../components/common/IconTheme';
import './Certificates.css';

const Certificates = () => {
  const { addNotification } = useAuth();
  const [certificates, setCertificates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [downloading, setDownloading] = useState(null);

  useEffect(() => {
    fetchCertificates();
  }, []);

  const fetchCertificates = async () => {
    try {
      setLoading(true);
      const response = await certificatesAPI.getStudentCertificates();
      if (response.data.success) {
        setCertificates(response.data.data.certificates);
      }
    } catch (error) {
      console.error('Erreur lors du chargement des certificats:', error);
      addNotification('Erreur lors du chargement des certificats', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = async (certificateId, courseTitle) => {
    try {
      setDownloading(certificateId);
      const response = await certificatesAPI.downloadCertificate(certificateId);
      
      // Créer un blob et télécharger le fichier
      const blob = new Blob([response.data], { type: 'application/pdf' });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      
      // Nom du fichier basé sur le titre du cours
      const fileName = `Certificat_${courseTitle.replace(/[^a-zA-Z0-9]/g, '_')}.pdf`;
      link.download = fileName;
      
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
      
      addNotification('Certificat téléchargé avec succès !', 'success');
    } catch (error) {
      console.error('Erreur lors du téléchargement:', error);
      addNotification('Erreur lors du téléchargement du certificat', 'error');
    } finally {
      setDownloading(null);
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('fr-FR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const getGradeColor = (grade) => {
    switch (grade) {
      case 'A+':
      case 'A':
        return 'success';
      case 'B+':
      case 'B':
        return 'info';
      case 'C+':
      case 'C':
        return 'warning';
      default:
        return 'secondary';
    }
  };

  if (loading) {
    return (
      <div className="main-content">
        <div className="text-center">
          <p>Chargement de vos certificats...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="main-content">
      <div className="card">
        <div className="card-header">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Icon name="trophy" size={IconSizes.md} color={IconColors.success} />
            <h1 className="card-title">Mes Certificats</h1>
          </div>
          <p style={{ color: 'var(--text-secondary)', margin: 0 }}>
            Vos certificats de completion de cours
          </p>
        </div>
      </div>

      {certificates.length === 0 ? (
        <div className="card">
          <div className="text-center py-5">
            <Icon name="trophy" size={IconSizes.xl} color={IconColors.gray} />
            <h3 className="mt-3">Aucun certificat</h3>
            <p className="text-muted">
              Vous n'avez pas encore de certificats. Complétez des cours pour obtenir vos premiers certificats !
            </p>
          </div>
        </div>
      ) : (
        <div className="certificates-grid">
          {certificates.map((cert) => (
            <div key={cert.certificateNumber} className="certificate-card">
              <div className="certificate-header">
                <div className="certificate-icon">
                  <Icon name="trophy" size={IconSizes.lg} color={IconColors.white} />
                </div>
                <div className="certificate-badges">
                  <span className={`grade-badge grade-${getGradeColor(cert.completion.grade)}`}>
                    {cert.completion.grade}
                  </span>
                  <span className="completion-badge">
                    {cert.completion.percentage}%
                  </span>
                </div>
              </div>
              
              <div className="certificate-content">
                <h3 className="certificate-title">{cert.course.title}</h3>
                <p className="certificate-description">{cert.course.description}</p>
                
                <div className="certificate-details">
                  <div className="detail-item">
                    <Icon name="tag" size={IconSizes.xs} color={IconColors.gray} />
                    <span>{cert.course.category}</span>
                  </div>
                  <div className="detail-item">
                    <Icon name="target" size={IconSizes.xs} color={IconColors.gray} />
                    <span>{cert.course.level}</span>
                  </div>
                  <div className="detail-item">
                    <Icon name="clock" size={IconSizes.xs} color={IconColors.gray} />
                    <span>{cert.course.duration}</span>
                  </div>
                </div>

                <div className="certificate-stats">
                  <div className="stat-item">
                    <span className="stat-label">Leçons complétées</span>
                    <span className="stat-value">
                      {cert.completion.completedLessons}/{cert.completion.totalLessons}
                    </span>
                  </div>
                  <div className="stat-item">
                    <span className="stat-label">Date d'émission</span>
                    <span className="stat-value">{formatDate(cert.certificate.issuedAt)}</span>
                  </div>
                </div>

                <div className="certificate-actions">
                  <button
                    className="btn btn-primary certificate-download-btn"
                    onClick={() => handleDownload(cert.certificateNumber, cert.course.title)}
                    disabled={downloading === cert.certificateNumber}
                  >
                    {downloading === cert.certificateNumber ? (
                      <>
                        <Icon name="spinner" size={IconSizes.xs} color={IconColors.white} />
                        Téléchargement...
                      </>
                    ) : (
                      <>
                        <Icon name="download" size={IconSizes.xs} color={IconColors.white} />
                        Télécharger PDF
                      </>
                    )}
                  </button>
                  
                  <div className="certificate-number">
                    <small>Certificat #{cert.certificateNumber}</small>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Certificates;
